package contexts_test

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/tokenstore"
)

// Probe: legacy contexts.json with contexts but a CLEARED current_context —
// the exact state `entire logout` leaves on main (File.Delete clears
// current_context and never reassigns). What happens to the remaining login's
// keychain tokens on migration?
func TestProbe_MigrationWithClearedCurrentContext(t *testing.T) {
	cfgDir := t.TempDir()
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	svc := tokenstore.CoreKeyringService("https://core.example")
	if err := tokenstore.Set(svc, "alice", "access-token"); err != nil {
		t.Fatalf("seed access: %v", err)
	}
	if err := tokenstore.Set(tokenstore.RefreshService(svc), "alice", "refresh-token"); err != nil {
		t.Fatalf("seed refresh: %v", err)
	}
	if err := tokenstore.Set(tokenstore.JurisdictionService("https://eu.example"), "alice", "juris-token"); err != nil {
		t.Fatalf("seed jurisdiction: %v", err)
	}

	legacy := contexts.File{
		CurrentContext: "", // logout cleared it; the login itself remains
		Contexts: []*contexts.Context{{
			Name:                  "core.example",
			CoreURL:               "https://core.example",
			Handle:                "alice",
			KeychainService:       svc,
			JurisdictionAudiences: []string{"https://eu.example"},
		}},
	}
	data, err := json.Marshal(legacy)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	legacyPath := filepath.Join(cfgDir, "contexts.json")
	if err := os.WriteFile(legacyPath, data, 0o600); err != nil {
		t.Fatalf("write legacy: %v", err)
	}

	f, err := contexts.Load(cfgDir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	t.Logf("loaded: current=%q contexts=%d", f.CurrentContext, len(f.Contexts))

	if _, statErr := os.Stat(legacyPath); statErr == nil {
		t.Logf("contexts.json: STILL PRESENT")
	} else {
		t.Logf("contexts.json: DELETED (%v)", statErr)
	}

	for _, probe := range []struct {
		label   string
		service string
	}{
		{"access", svc},
		{"refresh", tokenstore.RefreshService(svc)},
		{"jurisdiction", tokenstore.JurisdictionService("https://eu.example")},
	} {
		v, gerr := tokenstore.Get(probe.service, "alice")
		switch {
		case errors.Is(gerr, tokenstore.ErrNotFound):
			t.Logf("%-13s token: cleaned up", probe.label)
		case gerr != nil:
			t.Logf("%-13s token: error %v", probe.label, gerr)
		default:
			t.Errorf("%-13s token: ORPHANED, still readable (%q) with no metadata referencing it", probe.label, v)
		}
	}
}

